mapper.update:
UPDATE visitor
visitor_name = #{visitorName}, visitor_phone = #{visitorPhone}, visitor_type = #{visitorType}, visitor_status = #{visitorStatus}, visitor_finish_time = #{visitorFinishTime}, visitor_remark = #{visitorRemark},
WHERE id = #{id}

mapper.select:
SELECT v.*, u1.user_name AS owner_name, u2.user_name AS creater_name, vt.visitor_type_name FROM visitor v LEFT JOIN user u1 ON v.owner_id = u1.id LEFT JOIN user u2 ON v.visitor_creater = u2.id LEFT JOIN visitor_type vt ON v.visitor_type = vt.visitor_type_id
AND v.owner_id = #{ownerId}
AND v.visitor_type = #{visitorType}
AND v.visitor_status = #{visitorStatus}
AND v.visitor_name LIKE CONCAT('%', #{visitorName}, '%')
ORDER BY v.visitor_create_time DESC
